type Json = Record<string, unknown>
const img = (_id: string, w = 900, h = 1200): Json => ({ url: asset("tryFront"), width: w, height: h, alt: "Fotografia demonstrativa; resultado de IA simulado", focus: "50% 30%" })
const image = (p: {src: string; pos?: string}): Json => ({ ...img(""), url: p.src, focus: p.pos ?? "50% 30%" })
