const withFav = (p: Json): Json => ({ ...p, favorite: S.favorites.has(String(p.id)) })
const piece = (p: Json, role: string, warnings: string[] = []): Json => ({ product: withFav(p), role, warnings })

const fullById = (id: string): Json | undefined => FULL_PRODUCTS.find((p) => p.id === id)
const PREPARED: Json[] = LOOKS.map(l => ({
  id:l.id, title:l.title, note:l.note + " · Demonstração com fotografia preparada.", image:image(l.image),
  pieces:l.pieces.map(p => piece(fullById(p.productId)!, p.role)), origin:"match", version:1, parentId:null,
  prompt:l.title, createdAt:new Date().toISOString(), candidatesCount:products.length, saved:false, simulated:true,
}))
S.looks = PREPARED.slice(0,3).map(l => ({...l, origin:"generate"}))
S.saved = new Set(["la-fria"])
const decisions = new Map<string, {lookId:string; added:boolean}>()
/** Object URLs of photos selected in the prototype Perfil (kept in this browser only). */
const bodyUrls = new Map<string, string>()
let scenario: "normal" | "failed" | "no_results" = "normal"
let contract: "tryon" | "full" = "tryon"
export function configureDemo(input: {tokens?:number; scenario?:typeof scenario; signedIn?:boolean; contract?: typeof contract; plan?: "free" | "paid"; catalog?: "test" | "store" | "synthetic"}): void {
  if(input.tokens !== undefined) { S.tokens = input.tokens; T.coins = input.tokens }
  if(input.scenario) scenario = input.scenario
  if(input.signedIn !== undefined) S.signedIn = input.signedIn
  if(input.catalog) catalogMode = input.catalog
  if(input.contract) { contract = input.contract; S.looks = contract === "tryon" ? [] : PREPARED.slice(0,3).map(l => ({...l, origin:"generate"})) }
  products = contract === "tryon" ? (catalogMode === "store" ? STORE_PRODUCTS : catalogMode === "synthetic" ? TEST_PRODUCTS : TEST_MAIN) : FULL_PRODUCTS
  if(input.plan) { T.plan = input.plan; T.coins = PLAN_COINS[input.plan] }
}
export const demoContract = (): typeof contract => contract

/* ---------------------------------------------------------------- official try-on contract */

const POLICY = "2026-11-24-inline"
interface DemoPhoto { id: string; angle: PhotoAngle; at: number; url: string | null; validation: PhotoValidation }
const T = {
  /** Moedas: the demo starts on the paid plan (120); "Testar cenários" switches to the free plan (30). */
  plan: "paid" as "free" | "paid", coins: PLAN_COINS.paid as number, consent: false,
  /** Per angle: the approved photo in use and a newer candidate that did not pass. Object URLs only (never uploaded). */
  photos: new Map<PhotoAngle, { current: DemoPhoto | null; candidate: DemoPhoto | null }>(),
  keys: new Map<string, string>(), pendingSignUp: null as Json | null,
}
/** Object URL of a candidate that failed for a technical reason (the browser re-analyses it on "Tentar validar de novo"). */
export const revalidationSource = (angle: string): string | null => {
  const c = T.photos.get(angle as PhotoAngle)?.candidate
  return c && c.validation.status === "error" ? c.url : null
}
/** Demo product with variant ids, as apps/api returns it. */
const apiProduct = (p: Json): Json => { const { variantsWithIds, ...rest } = p; return { ...withFav(rest), variants: variantsWithIds } }
function tryOnLook(product: Json, variantId: string | null, parent: Json | null): Json {
  const id = "l" + ++S.seq
  const variants = product.variantsWithIds as Json[]
  const variant = variants.find(v => v.id === variantId) ?? variants.find(v => v.available) ?? null
  const lineageId = parent ? String(parent.lineageId) : "lin" + S.seq
  return {
    id, title: String(product.name), note: null,
    // Demonstration only: the catalog image, never presented as a try-on of the user's photo.
    image: { ...((product.images as Json[])[0] ?? img("")), alt: `Imagem demonstrativa da peça ${String(product.name)}; não é uma prova na sua foto` },
    pieces: [{ role: "chosen", product: { ...apiProduct(product), variants: variant ? [variant] : [] },
      warnings: ["Imagem demonstrativa: não é uma prova real na sua foto", product.simulationOnly ? "Foto do anúncio; preço, tamanho e estoque não verificados. Link direto, sem comissão." : "Produto de teste (não é oferta real; sem estoque nem link)"] }],
    simulated: true,
    prompt: null, origin: parent ? "tryon" : "generate", version: parent ? Number(parent.version) + 1 : 1,
    parentId: parent ? parent.id : null, lineageId, createdAt: new Date().toISOString(), candidatesCount: 0, saved: false,
  }
}
const photoJson = (p: DemoPhoto, inUse: boolean): Json => ({
  id: p.id, angle: p.angle, inUse, status: inUse ? "ready" : "rejected",
  // Only the person's own selected file is shown (object URL); never a prepared photo of someone else.
  image: { url: p.url ?? "", width: null, height: null, alt: "Sua foto (fica só neste navegador)", focus: "50% 25%" },
  issues: p.validation.issues.filter((i) => i.level !== "advice").map((i) => i.message),
  advice: p.validation.issues.filter((i) => i.level === "advice").map((i) => i.message),
  revalidatable: !inUse && p.validation.status === "error",
  validation: { status: p.validation.status, framing: p.validation.framing, supports: p.validation.supports, measuredAngle: p.validation.measuredAngle, persons: p.validation.persons, version: p.validation.version, issues: p.validation.issues },
  uploadedAt: new Date(p.at).toISOString(), expiresAt: new Date(p.at + 7 * 86_400_000).toISOString(),
})
const photoView = (): Json[] => [...T.photos.values()].flatMap((s) => [...(s.current ? [photoJson(s.current, true)] : []), ...(s.candidate ? [photoJson(s.candidate, false)] : [])])
/** Same rules as the API (packages/contracts/src/photo-validation.ts) on measurements taken in this browser. */
function settlePhoto(angle: PhotoAngle, url: string | null, analysis: PoseAnalysis | null | undefined, id = "photo-" + angle + "-" + ++S.seq): DemoPhoto {
  const validation = analysis ? evaluatePose(analysis, angle) : analyzerFailure(angle, "web-unavailable+pose-rules/1")
  const photo: DemoPhoto = { id, angle, at: Date.now(), url, validation }
  const slot = T.photos.get(angle) ?? { current: null, candidate: null }
  if (validation.status === "approved") T.photos.set(angle, { current: photo, candidate: null })
  else T.photos.set(angle, { current: slot.current, candidate: photo })
  return photo
}
const activeJob = (): Job | undefined => [...S.jobs.values()].find(j => !j.cancelled && !j.settled && Date.now() - j.at < 5200)
/** Same rule-based reading as the API (category words, colour, "até R$ N"), on the demo catalog. */
function searchCatalog(prompt: string, budget?: { value?: number; mode?: "require" | "prefer" | "off" } | null): Res {
  if (!prompt.trim()) return err(422, "validation", "Diga o que você procura, por exemplo a peça, a cor ou o orçamento.", { prompt: "Descreva o que procura." })
  // QA-013: exactly the API rules (packages/contracts/src/search-rules.ts) on the catalog in use.
  const result = runSearch(prompt, products.map((p) => ({
    id: String(p.id), name: String(p.name), category: p.category as { id: string; label: string },
    priceMinor: p.price ? Math.round(Number((p.price as Json).amount) * 100) : null,
    hasAvailableVariant: (p.variantsWithIds as Json[]).some((v) => v.available === true),
    tryOnReady: p.tryOnReady === true,
  })), budget ?? null)
  const items = result.items.map(({ id, failed }) => ({ product: apiProduct(byId(id)!), usedInLook: false, failed }))
  return ok({ source: "curated_catalog", catalog: catalogMode === "store" ? "store_references" : "test_catalog", interpretation: result.interpretation, items, total: items.length })
}

function startTryOn(input: { productId: string; variantId: string | null; parentId: string | null }, key: string | null): Res {
  if (!key || !/^[A-Za-z0-9_-]{8,128}$/.test(key)) return err(400, "validation", "Cabeçalho Idempotency-Key ausente ou inválido.")
  const replay = T.keys.get(key)
  if (replay) { const j = S.jobs.get(replay); if (j) return ok(jobView(j), 202) }
  if (!T.consent) return err(403, "consent_required", "Aceite o termo de uso da foto para usar o provador.")
  const front = T.photos.get("front")?.current
  if (!front) return err(409, "photo_required", "Adicione no Perfil uma foto de frente aprovada antes de gerar.")
  const product = byId(input.productId)
  if (!product) return err(422, "unprocessable", "Esta peça não está mais disponível.")
  const group = CATEGORY_GROUP[String((product.category as Json).id)]
  if (!group) return err(422, "category_not_renderable", "Esta categoria ainda não é compatível com o provador. Escolha uma peça individual de uma categoria disponível.")
  if (front.validation.status !== "approved" || !front.validation.supports[group]) return err(409, "photo_framing_insufficient", "Sua foto de frente mostra o corpo só até os joelhos: ela serve para peças de cima. Para calças, saias e vestidos, envie no Perfil uma foto de corpo inteiro.")
  const parent = input.parentId ? lookById(input.parentId) ?? null : null
  if (input.parentId && !parent) return err(403, "forbidden", "Versão indisponível para esta conta.")
  if (activeJob()) return err(409, "conflict", "Já existe um pedido em andamento.")
  if (T.coins < COINS_PER_REQUEST) return err(402, "insufficient_tokens", `Suas moedas de hoje acabaram (cada geração usa ${COINS_PER_REQUEST}). O saldo renova à meia-noite (UTC).`)
  const look = tryOnLook(product, input.variantId, parent)
  const outcome = scenario === "failed" || product.simulateFailure === true ? "failed" : "succeeded"
  scenario = "normal"
  const job: Job = { id: "j" + S.seq, kind: parent ? "tryon" : "generate", at: Date.now(), cost: COINS_PER_REQUEST, lookId: String(look.id), cancelled: false, result: look, settled: false, outcome, limiting: [] }
  S.jobs.set(job.id, job)
  T.keys.set(key, job.id)
  return ok(jobView(job), 202)
}
export function resetDemo(): void {
  S.signedIn=true; S.tokens=PLAN_COINS.paid; S.favorites=new Set(["blazer-la-fria","tote-couro"]); S.saved=new Set(["la-fria"])
  S.looks=PREPARED.slice(0,3).map(l => ({...l, origin:"generate"})); S.jobs.clear(); S.seq=0; decisions.clear(); scenario="normal"
  S.body.clear(); S.user={id:"u-preview",name:"Conta demonstração",email:"demo@example.com",emailVerified:true,providers:["password"],avatarUrl:null}
  S.measurements={size:"M",bustCm:90,waistCm:72,hipsCm:98,heightCm:168,useInSearch:true}
  S.preferences=[{id:"dia",name:"Dia a dia",rules:structuredClone(rules)},{id:"evento",name:"Evento",rules:structuredClone(rules)}]
  T.plan="paid"; T.coins=PLAN_COINS.paid; T.consent=false; T.photos.clear(); T.keys.clear(); T.pendingSignUp=null
  if(contract==="tryon") S.looks=[]
}
const lookById = (id: string): Json | undefined => [...S.looks, ...PREPARED].find((l) => l.id === id)
const withSaved = (l: Json): Json => ({ ...l, saved: S.saved.has(String(l.id)), pieces: (l.pieces as Json[]).map((p) => ({ ...p, product: withFav(p.product as Json) })) })

function makeLook(kind: Job["kind"], input: Json, parent?: Json): Json {
  const id = "l" + ++S.seq
  const prompt = String(input.prompt ?? "")
  const normalized=prompt.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
  const style=INTENT_HINTS.find(h=>h.words.some(w=>normalized.includes(w)))?.style
  const matching=LOOKS.filter(l=>!style || l.style===style)
  const source=matching[(S.seq-1)%matching.length] ?? LOOKS[0]!
  const chosen=((input.productIds as string[]|undefined)??[]).map(byId).filter((p):p is Json=>!!p)
  const prepared=PREPARED.find(l=>l.id===source.id)!
  const dressing=input.mode==="dress" || kind==="tryon"
  const searchRules=parseRules(input.rules ?? S.preferences.find(p=>p.id===input.preferenceId)?.rules ?? rules)
  const basePieces=(prepared.pieces as Json[]).filter(p=>!chosen.some(c=>c.id===(p.product as Json).id) && failures(p.product as Json,searchRules).length===0)
  if(!dressing && basePieces.length===0) basePieces.push(...products.filter(p=>failures(p,searchRules).length===0 && !chosen.some(c=>c.id===p.id)).slice(0,3).map(p=>piece(p,"look")))
  const pieces=[...chosen.map(p=>piece(p,"chosen")), ...(dressing ? [] : basePieces)].slice(0,6)
  if(kind==="edit" && parent) {
    const instruction=String(input.instruction??"").toLowerCase()
    const original=LOOKS.find(l=>l.id===parent.sourceId || l.id===parent.id) ?? source
    const edit=original.edits.find(e=>e.keywords.some(k=>instruction.includes(k)))
    return {...parent,id,image:edit ? image(edit.image) : parent.image, origin:"edit",version:Number(parent.version)+1,parentId:parent.id,saved:false,note:"Edição simulada: " + (edit?.note ?? "fotografia preparada mantida; nenhuma IA foi executada.")}
  }
  return {...prepared,id,sourceId:source.id,pieces,prompt,origin:kind,version:1,parentId:parent?.id??null,saved:false,
    title:dressing ? "Prova demonstrativa das peças selecionadas" : source.title,
    note:dressing ? "Simulação de fluxo: a fotografia preparada não representa suas fotos ou as peças enviadas." : source.note+" · Fotografia preparada, sem geração real.",
    candidatesCount:dressing ? 0 : products.length,createdAt:new Date().toISOString()}
}

function failures(p: Json, r: ReturnType<typeof parseRules>): string[] {
  const out: string[]=[]
  if((r.minRating.mode==="require" && Number(p.rating??0)<r.minRating.value) || (r.missingRating==="exclude" && p.rating===null)) out.push("rating")
  if(r.minReviews.mode==="require" && Number(p.reviewsCount??0)<r.minReviews.value) out.push("reviews")
  if(r.excludedPartners.includes(String((p.partner as Json).id))) out.push("partners")
  if(r.budget.mode==="require" && Number((p.price as Json).amount)>r.budget.value) out.push("budget")
  if(r.advanced.sellerRating.mode==="require" && Number(p.sellerRating??0)<r.advanced.sellerRating.value) out.push("sellerRating")
  if(r.advanced.maxDeliveryDays.mode==="require" && (p.deliveryDays===null || Number(p.deliveryDays)>r.advanced.maxDeliveryDays.value)) out.push("delivery")
  if(r.advanced.avoidColors.some(c=>String(p.color).toLowerCase()===c.toLowerCase())) out.push("colors")
  if(r.advanced.fit.mode==="require" && p.fit!==r.advanced.fit.value) out.push("fit")
  const size=p.kind==="sapato" ? r.sizes.shoes : p.kind==="calca" ? r.sizes.bottom : r.sizes.top
  if(r.onlyAvailableSize && size && !["bolsa","acessorio"].includes(String(p.kind)) && !(p.variants as {label:string;available:boolean}[]).some(v=>v.label===size && v.available)) out.push("size")
  return out
}

const STEPS = ["Interpretando o pedido", "Buscando peças nos parceiros", "Combinando as peças", "Gerando a imagem"]
function jobView(j: Job): Json {
  const t = Date.now() - j.at
  const base = { id: j.id, kind: j.kind, cost: j.cost, candidatesCount: products.length, limiting: j.limiting }
  if (j.cancelled) return { ...base, status: "cancelled", charged: false }
  if (t < 900) return { ...base, status: "queued", step: null, progress: null, charged: false }
  if (t < 5200) {
    const p = (t - 900) / 4300
    return { ...base, status: "running", step: contract === "tryon" ? "Vestindo a peça escolhida" : j.kind === "generate" ? STEPS[Math.min(3, Math.floor(p * 4))] : j.kind === "edit" ? "Aplicando a edição" : "Vestindo as peças nas suas fotos", progress: p, charged: false }
  }
  if (j.outcome !== "succeeded") { j.settled = true; return {...base, status:j.outcome, charged:false, error:j.outcome==="failed" ? {code:"demo_failure",message: contract === "tryon" ? "Falha simulada do provador. Nenhuma moeda foi debitada." : "Falha simulada. Tente novamente; nada foi cobrado."} : null} }
  if(!j.settled) { S.looks.unshift(j.result); if (contract === "tryon") T.coins -= j.cost; else S.tokens-=j.cost; j.settled=true }
  if (!S.looks.some((l) => l.id === j.lookId)) return { ...base, status: "failed", charged: false }
  return { ...base, status: "succeeded", progress: 1, charged: true, lookId: j.lookId, ...(contract === "tryon" ? { candidatesCount: null, versionId: j.lookId, version: Number(j.result.version) } : {}) }
}

type Res = { status: number; body?: unknown }
const err = (status: number, code: string, message: string, fields?: Json): Res => ({ status, body: { error: { code, message, fields } } })
const ok = (body: unknown, status = 200): Res => ({ status, body })

function startJob(kind: Job["kind"], input: Json, parent?: Json): Res {
  if([...S.jobs.values()].some(j=>!j.cancelled && !j.settled && Date.now()-j.at<5200)) return err(409,"busy","Um pedido já está em andamento.")
  const cost = kind === "generate" ? 6 : kind === "edit" ? 2 : 4
  if (S.tokens < cost) return err(402, "insufficient_tokens", `Saldo insuficiente: faltam ${cost - S.tokens} moedas.`)
  const look = makeLook(kind, input, parent)
  const r=parseRules(input.rules ?? S.preferences.find(p=>p.id===input.preferenceId)?.rules ?? rules)
  const limits: Json[]=[]
  if(kind==="generate" && input.mode!=="dress") {
    if(r.budget.mode==="require" && r.budget.value < Math.min(...PRODUCTS.map(p=>p.price))) limits.push({id:"budget",label:"Orçamento",removed:products.length,total:products.length,unlocks:true})
    if(r.minRating.mode==="require" && !PRODUCTS.some(p=>(p.rating??0)>=r.minRating.value)) limits.push({id:"rating",label:"Nota mínima",removed:products.length,total:products.length,unlocks:true})
    if(PARTNERS.every(p=>r.excludedPartners.includes(p.id))) limits.push({id:"partners",label:"Lojas excluídas",removed:products.length,total:products.length,unlocks:true})
    const eligible=products.filter(p=>failures(p,r).length===0)
    if(!eligible.length && !limits.length) {
      const ids=[...new Set(products.flatMap(p=>failures(p,r)))]
      const labels: Record<string,string>={rating:"Nota mínima",reviews:"Avaliações",partners:"Lojas",size:"Tamanho disponível",budget:"Orçamento",sellerRating:"Nota da loja",delivery:"Prazo",colors:"Cores",fit:"Modelagem"}
      for(const id of ids) limits.push({id,label:labels[id]??id,removed:products.filter(p=>failures(p,r).includes(id)).length,total:products.length,unlocks:products.some(p=>failures(p,r).every(f=>f===id))})
    }
    if(r.budget.mode==="require" && r.budget.scope==="look" && (look.pieces as Json[]).reduce((sum,p)=>sum+Number(((p.product as Json).price as Json).amount),0)>r.budget.value && !limits.some(l=>l.id==="budget")) limits.push({id:"budget",label:"Orçamento do look",removed:0,total:products.length,unlocks:true})
  }
  const outcome=scenario==="normal" ? (limits.length ? "no_results" : "succeeded") : scenario
  scenario="normal"
  const job: Job = { id: "j"+S.seq,kind,at:Date.now(),cost,lookId:String(look.id),cancelled:false,result:look,settled:false,outcome,limiting:limits }
  S.jobs.set(job.id,job)
  return ok(jobView(job), 202)
}

export function handle(method: string, path: string, url: URL, body: Json | null, headers: Record<string, string> = {}): Res {
  path = decodeURIComponent(path)
  for(const job of S.jobs.values()) jobView(job)
  // Official contract: what the engine lacks answers exactly like the API (not implemented yet).
  if (contract === "tryon") {
    if (method === "GET" && path === "/explore/hero") return ok({ hero: null })
    const notYet = ["/closet", "/preferences", "/studio/match", "/uploads/references", "/plans"]
    if (notYet.some((p) => path === p || path.startsWith(p + "/")) || /\/studio\/looks\/[^/]+\/(edits|candidates)$/.test(path)) return err(503, "service_unavailable", "Esta funcionalidade ainda não foi implementada.")
  }
  const m = (re: RegExp): RegExpMatchArray | null => path.match(re)
  const session = (): Res => ok({ accessToken: "preview-token", user: S.user })

  // auth
  if (method === "POST" && path === "/auth/refresh") return S.signedIn ? session() : err(401, "unauthorized", "Sem sessão.")
  if (method === "POST" && path === "/auth/sign-in") {
    if (!body?.email || !body?.password) return err(422, "validation", "Revise os campos.")
    S.signedIn = true
    S.user = { ...S.user, email: String(body.email), name: S.user.name === "Visitante" ? String(body.email).split("@")[0] : S.user.name }
    return session()
  }
  if (method === "POST" && path === "/auth/sign-up") {
    // Same as the real API: an account pending e-mail confirmation, never a session.
    T.pendingSignUp = { ...S.user, name: String(body?.name ?? ""), email: String(body?.email ?? ""), emailVerified: true }
    return ok({ status: "verification_required" }, 202)
  }
  if (method === "POST" && path === "/auth/email/verify") {
    if (!T.pendingSignUp || !/^demo-/.test(String(body?.tokenHash ?? ""))) return err(400, "invalid_token", "Este link de confirmação é inválido ou já foi usado.")
    S.user = T.pendingSignUp; T.pendingSignUp = null; S.signedIn = true
    return session()
  }
  if (method === "POST" && path === "/auth/email/verify/resend" && !S.signedIn) return ok(null, 204)
  if (method === "POST" && path === "/auth/sign-out") {
    S.signedIn = false
    return ok(null, 204)
  }
  if (method === "POST" && ["/auth/password/forgot", "/auth/password/reset"].includes(path)) return ok(null, 204)

  // public
  if (method === "GET" && path === "/explore/hero") return ok({ hero: { product: withFav(products[0]!), image: image(LOOKS[0]!.image) } })
  if (method === "GET" && path === "/catalog/source" && contract === "tryon") return ok(catalogMode === "store" ? { id: "store_references", label: "SHEIN Brasil — referências para simulação", capabilities: { ...TEST_CATALOG_CAPABILITIES, price: "none", productLinks: true } } : { id: "test_catalog", label: "Catálogo de teste (dados sintéticos)", capabilities: TEST_CATALOG_CAPABILITIES })
  if (method === "GET" && path === "/catalog/facets" && contract === "tryon") {
    // Same answer shape as the API: facets of the test catalog; no price range is claimed.
    const tally = (key: "category" | "partner") => [...products.reduce((acc, p) => { const o = p[key] as Json; const k = String(o.id); acc.set(k, { id: k, label: String(o.label ?? o.name), count: (acc.get(k)?.count ?? 0) + 1 }); return acc }, new Map<string, { id: string; label: string; count: number }>()).values()]
    return ok({ categories: tally("category"), partners: tally("partner"), priceRange: null, total: products.length })
  }
  if (method === "GET" && path === "/catalog/facets") {
    const count = (key: "category" | "partner", id: string): number => products.filter((p) => (p[key] as Json).id === id).length
    return ok({
      categories: ORDER.map((k) => ({ id: (KINDS[k] as (typeof KINDS)[string]).cat[0], label: (KINDS[k] as (typeof KINDS)[string]).cat[1], count: count("category", (KINDS[k] as (typeof KINDS)[string]).cat[0]) })),
      partners: PARTNERS.map((p) => ({ id: p.id, label: p.name, count: count("partner", p.id) })),
      priceRange: { min: Math.min(...PRODUCTS.map(p=>p.price)), max: Math.max(...PRODUCTS.map(p=>p.price)), currency: "BRL" },
      total: products.length,
    })
  }
  if (method === "GET" && path === "/catalog/products") {
    const q = (url.searchParams.get("q") ?? "").toLowerCase()
    const cat = url.searchParams.get("category")
    const partner = url.searchParams.get("partner")
    const min = url.searchParams.get("priceMin")
    const max = url.searchParams.get("priceMax")
    let list = products.filter((p) => {
      const price = (p.price as Json | null)?.amount as number | undefined
      const text = `${String(p.name)} ${String((p.category as Json).label)} ${String((p.partner as Json).name)} ${String(p.color)}`.toLowerCase()
      return (!q || text.includes(q)) && (!cat || (p.category as Json).id === cat) && (!partner || (p.partner as Json).id === partner) && (!min || (price !== undefined && price >= Number(min))) && (!max || (price !== undefined && price <= Number(max)))
    })
    if (url.searchParams.get("favorites")) list = list.filter((p) => S.favorites.has(String(p.id)))
    const sort = url.searchParams.get("sort")
    const price = (p: Json): number => ((p.price as Json | null)?.amount as number | undefined) ?? Infinity
    if (sort === "price_asc") list = [...list].sort((a, b) => price(a) - price(b))
    if (sort === "price_desc") list = [...list].sort((a, b) => (price(b) === Infinity ? -1 : price(b)) - (price(a) === Infinity ? -1 : price(a)))
    if (sort === "newest") list = [...list].reverse()
    const start = Number(url.searchParams.get("cursor") ?? 0)
    const limit = Number(url.searchParams.get("limit") ?? 24)
    return ok({ items: list.slice(start, start + limit).map(contract === "tryon" ? apiProduct : withFav), nextCursor: start + limit < list.length ? String(start + limit) : null, total: list.length })
  }
  const prod = m(/^\/catalog\/products\/(.+)$/)
  if (method === "GET" && prod) {
    const p = byId(prod[1] as string)
    return p ? ok(contract === "tryon" ? apiProduct(p) : withFav(p)) : err(404, "not_found", "Peça não encontrada.")
  }
  if (method === "GET" && path === "/studio/config" && contract === "tryon") {
    return ok({ costs: { generate: COINS_PER_REQUEST, edit: null, tryOn: COINS_PER_REQUEST }, unit: COIN_UNIT,
      plans: [{ id: "free", name: PLAN_LABEL.free, coinsPerPeriod: PLAN_COINS.free, period: "day" }, { id: "paid", name: PLAN_LABEL.paid, coinsPerPeriod: PLAN_COINS.paid, period: "day" }],
      costGaps: ["edit", "monthly_limit", "paid_plan_price", "reset_time_confirmation"], generationMode: "simulated", realProvider: null, maxReferences: 0, maxChosenPieces: 1, maxPromptLength: 500,
      budget: { min: 0, max: 0, step: 1, currency: "BRL" }, acceptedImageTypes: ["image/jpeg", "image/png", "image/webp"], maxImageBytes: 12 * 1024 * 1024, minImageHeight: 600,
      sizes: { top: [], bottom: [], shoes: [] }, photoPolicyVersion: POLICY, quotaStatus: "provisional",
      capabilities: { mode: "single_piece_try_on", search: true, searchScope: "curated_catalog", dress: true, adjustments: false, bodyPhotoRequired: true, closet: false,
        generation: true, edits: false, match: false, references: false, preferences: false, measurements: false, plans: false, candidates: false } })
  }
  if (method === "GET" && path === "/studio/config") {
    // Historical full prototype, with the approved unit and generation cost; edit cost is not defined.
    return ok({ costs: { generate: COINS_PER_REQUEST, edit: null, tryOn: COINS_PER_REQUEST }, unit: COIN_UNIT, maxReferences: 3, maxChosenPieces: 6, maxPromptLength: 500, budget: { min: 100, max: 3000, step: 50, currency: "BRL" }, acceptedImageTypes: ["image/jpeg", "image/png", "image/webp"], maxImageBytes: 12 * 1024 * 1024, minImageHeight: 0, sizes: { top: ["PP", "P", "M", "G", "GG"], bottom: ["36", "38", "40", "42", "44"], shoes: ["35", "36", "37", "38", "39"] } })
  }
  // Approved amounts only; the paid plan price is NOT defined, so none is shown.
  if (method === "GET" && path === "/plans") return ok({ items: [{ id: "free", name: PLAN_LABEL.free, tokensPerPeriod: PLAN_COINS.free, period: "day", price: null }, { id: "paid", name: PLAN_LABEL.paid, tokensPerPeriod: PLAN_COINS.paid, period: "day", price: null }] })

  if (!S.signedIn) return err(401, "unauthorized", "Entre para continuar.")

  // account
  if (method === "GET" && path === "/me") return ok(S.user)
  if (method === "PATCH" && path === "/me") {
    S.user = { ...S.user, ...(body ?? {}) }
    return ok(S.user)
  }
  if (method === "POST" && path === "/privacy/deletion-requests") {
    if (body?.confirm !== true) return err(422, "validation", "Confirme o pedido de exclusão da sua conta.")
    resetDemo(); S.looks=[]; S.saved.clear(); S.favorites.clear(); S.body.clear()
    S.signedIn = false
    return ok({ requestId: "demo-deletion", status: "pending" }, 202)
  }
  if (method === "DELETE" && path === "/me") {
    resetDemo(); S.looks=[]; S.saved.clear(); S.favorites.clear(); S.body.clear()
    S.signedIn = false
    return ok(null, 204)
  }
  if(method==="POST" && path==="/auth/email/verify/resend") { S.user.emailVerified=true; return ok(null,204) }
  if(method==="POST" && path==="/auth/password/change") return ok(null,204)
  if (method === "GET" && path === "/me/balance" && contract === "tryon") return ok({ tokens: T.coins, plan: { id: T.plan, name: PLAN_LABEL[T.plan], tokensPerPeriod: PLAN_COINS[T.plan], period: "day", price: null }, renewsAt: new Date(Date.now() + 86_400_000).toISOString() })
  if (method === "GET" && path === "/me/balance") return ok({ tokens: S.tokens, plan: { id: "paid", name: PLAN_LABEL.paid, tokensPerPeriod: PLAN_COINS.paid, period: "day", price: null }, renewsAt: new Date(Date.now() + 86_400_000).toISOString() })
  if (path === "/me/measurements") {
    if (method === "PUT" && body) S.measurements = body
    return ok(S.measurements)
  }
  if (method === "POST" && path === "/privacy/consents") {
    if (body?.version !== POLICY) return err(409, "consent_version_mismatch", "O termo foi atualizado. Recarregue a página.")
    T.consent = true
    return ok({ id: "consent-demo", version: POLICY, purpose: "body_photo_try_on" }, 201)
  }
  if (method === "GET" && path === "/me/body-photos" && contract === "tryon") return ok({ items: photoView(), consent: { policyVersion: POLICY, accepted: T.consent }, requiredAngles: ["front"], validator: { kind: "local_pose_model_in_browser", available: true } })
  const tp = m(/^\/me\/body-photos\/(front|side|profile)(\/revalidate)?$/)
  if (tp && contract === "tryon") {
    const angle = tp[1] as PhotoAngle
    if (method === "DELETE") { T.photos.delete(angle); return ok(null, 204) }
    if (method === "POST" && tp[2]) {
      const c = T.photos.get(angle)?.candidate
      if (!c || c.validation.status !== "error") return err(409, "conflict", "Não há validação pendente para esta foto.")
      const p = settlePhoto(angle, c.url, body?.analysis as PoseAnalysis | null | undefined, c.id)
      return ok(photoJson(p, p.validation.status === "approved"))
    }
    if (method === "PUT" && !tp[2]) {
      if (!T.consent) return err(403, "consent_required", "Aceite o termo de uso da foto antes de enviar.")
      const mime = String(body?.mime ?? "")
      if (!["image/jpeg", "image/png", "image/webp"].includes(mime)) return err(422, "invalid_image", "Use uma foto JPEG, PNG ou WebP.")
      if (Number(body?.sizeBytes ?? 0) > 12 * 1024 * 1024) return err(413, "payload_too_large", "A foto passa de 12 MB. Escolha uma menor.")
      const p = settlePhoto(angle, typeof body?.localUrl === "string" ? body.localUrl : null, body?.analysis as PoseAnalysis | null | undefined)
      return ok(photoJson(p, p.validation.status === "approved"))
    }
  }
  if (method === "GET" && path === "/me/body-photos") return ok({ items: [...S.body].map(([angle, at]) => ({ angle, image: bodyUrls.get(angle) ? { url: bodyUrls.get(angle), width: null, height: null, alt: "Sua foto (fica só neste navegador)", focus: "50% 25%" } : img("body"), status: Date.now() - at < 2500 ? "processing" : "ready", issues: [], uploadedAt: new Date(at).toISOString() })) })
  const bp = m(/^\/me\/body-photos\/(front|side|profile)$/)
  if (bp) {
    if (method === "DELETE") {
      S.body.delete(bp[1] as string)
      bodyUrls.delete(bp[1] as string)
      return ok(null, 204)
    }
    S.body.set(bp[1] as string, Date.now())
    if (typeof body?.localUrl === "string") bodyUrls.set(bp[1] as string, body.localUrl)
    return ok({ angle: bp[1], image: bodyUrls.get(bp[1] as string) ? { url: bodyUrls.get(bp[1] as string), width: null, height: null, alt: "Sua foto", focus: "50% 25%" } : img("body"), status: "processing", issues: [] })
  }
  if (method === "DELETE" && path === "/me/body-data") {
    S.body.clear()
    S.measurements = { size: null, bustCm: null, waistCm: null, hipsCm: null, heightCm: null, useInSearch: true }
    return ok(null, 204)
  }

  // closet
  if (method === "GET" && path === "/closet") {
    const looks = [...new Map([...S.looks, ...PREPARED].map(l => [String(l.id), l])).values()].filter((l) => S.saved.has(String(l.id))).map(withSaved)
    const fromLooks = new Map<string, Json>()
    looks.forEach((l) => (l.pieces as Json[]).forEach((p) => fromLooks.set(String((p.product as Json).id), p.product as Json)))
    const pieces = [...S.favorites].map((id) => ({ product: withFav(byId(id) as Json), via: "favorite", savedAt: null }))
    fromLooks.forEach((p, id) => !S.favorites.has(id) && pieces.push({ product: withFav(p), via: "look", savedAt: null }))
    return ok({ pieces, looks })
  }
  const cp = m(/^\/closet\/pieces\/(.+)$/)
  if (cp) {
    if (method === "PUT") S.favorites.add(cp[1] as string)
    else S.favorites.delete(cp[1] as string)
    return ok(null, 204)
  }
  const cl = m(/^\/closet\/looks\/(.+)$/)
  if (cl) {
    if (method === "PUT") S.saved.add(cl[1] as string)
    else S.saved.delete(cl[1] as string)
    return ok(null, 204)
  }

  // preferences
  if (method === "GET" && path === "/preferences") return ok({ items: S.preferences, defaultId: "dia" })
  const pr = m(/^\/preferences\/(.+)$/)
  if (method === "PATCH" && pr) {
    const p = S.preferences.find((x) => x.id === pr[1])
    if (!p) return err(404, "not_found", "Preferência não encontrada.")
    p.rules = body?.rules
    return ok(p)
  }

  // studio
  if (method === "POST" && path === "/uploads/references") {
    S.seq++
    return ok({ id: `ref${S.seq}`, image: img("ref"), sizeBytes: body?.sizeBytes ?? null, mime: body?.mime ?? "image/jpeg" }, 201)
  }
  if (contract === "tryon") {
    const key = headers["idempotency-key"] ?? null
    if (method === "POST" && path === "/studio/searches") return searchCatalog(String(body?.prompt ?? ""), ((body?.rules as Json | null | undefined)?.budget as never) ?? null)
    if (method === "POST" && path === "/studio/generations") {
      if (Array.isArray(body?.productIds) && body.productIds.length !== 1) return err(422, "single_piece_only", "Nesta fase o provador veste exatamente uma peça do catálogo por vez.")
      const productId = String(body?.productId ?? (body?.productIds as string[] | undefined)?.[0] ?? "")
      return startTryOn({ productId, variantId: (body?.variantId as string | null | undefined) ?? null, parentId: null }, key)
    }
    if (method === "POST" && path === "/studio/try-ons") {
      const ids = (body?.productIds as string[] | undefined) ?? []
      if (ids.length !== 1) return err(422, "single_piece_only", "Nesta fase o provador veste exatamente uma peça do catálogo por vez.")
      return startTryOn({ productId: ids[0] as string, variantId: (body?.variantId as string | null | undefined) ?? null, parentId: String(body?.sourceLookId ?? "") }, key)
    }
    if (method === "GET" && path === "/studio/jobs") {
      const active = activeJob()
      return ok({ items: active ? [jobView(active)] : [] })
    }
    const vs = m(/^\/studio\/looks\/(.+)\/versions$/)
    if (method === "GET" && vs) {
      const l = lookById(vs[1] as string)
      if (!l) return err(404, "not_found", "Look não encontrado.")
      return ok({ items: S.looks.filter(x => x.lineageId === l.lineageId).sort((a, b) => Number(a.version) - Number(b.version)).map(withSaved) })
    }
    if (method === "GET" && path === "/studio/looks") {
      const latest = new Map<string, Json>()
      for (const l of S.looks) if (!latest.has(String(l.lineageId))) latest.set(String(l.lineageId), l)
      return ok({ items: [...latest.values()].slice(0, 12).map(withSaved) })
    }
  }
  if (method === "POST" && path === "/studio/generations") {
    if (!body?.prompt && !(body?.productIds as string[] | undefined)?.length && !(body?.referenceIds as string[] | undefined)?.length) return err(422, "validation", "Descreva o look ou escolha uma peça.")
    return startJob("generate", body ?? {})
  }
  const ed = m(/^\/studio\/looks\/(.+)\/edits$/)
  if (method === "POST" && ed) {
    const parent = lookById(ed[1] as string)
    return parent ? startJob("edit", body ?? {}, parent) : err(404, "not_found", "Look não encontrado.")
  }
  if (method === "POST" && path === "/studio/try-ons") return startJob("tryon", body ?? {})
  const jb = m(/^\/studio\/jobs\/([^/]+)(\/cancel)?$/)
  if (jb) {
    const j = S.jobs.get(jb[1] as string)
    if (!j) return err(404, "not_found", "Pedido não encontrado.")
    if (method === "POST" && jb[2] && !j.settled) j.cancelled = true
    return ok(jobView(j))
  }
  if (method === "GET" && path === "/studio/looks") return ok({ items: S.looks.slice(0, 12).map(withSaved) })
  const cand = m(/^\/studio\/looks\/(.+)\/candidates$/)
  if (method === "GET" && cand) {
    const look = lookById(cand[1] as string)
    const inLook = new Set(((look?.pieces as Json[]) ?? []).map((p) => (p.product as Json).id))
    const pool = [...((look?.pieces as Json[]) ?? []).map((p) => p.product as Json), ...products.filter((p) => !inLook.has(p.id))]
    return ok({ items: pool.map((p, i) => ({ product: withFav(p), usedInLook: inLook.has(p.id), failed: !inLook.has(p.id) && i % 5 === 4 ? ["Nota mínima do produto"] : [] })) })
  }
  const lk = m(/^\/studio\/looks\/(.+)$/)
  if (method === "GET" && lk) {
    const l = lookById(lk[1] as string)
    return l ? ok(withSaved(l)) : err(404, "not_found", "Look não encontrado.")
  }
  if (method === "GET" && path === "/studio/match/deck") return ok({ items: PREPARED.filter(l=>l.id!==url.searchParams.get("lookId")).map(withSaved) })
  if (method === "POST" && path === "/studio/match/decisions") {
    S.seq++
    const decisionId = "d"+S.seq+":"+String(body?.lookId)
    decisions.set(decisionId,{lookId:String(body?.lookId),added:body?.decision==="save" && !S.saved.has(String(body?.lookId))})
    if (body?.decision === "save") S.saved.add(String(body.lookId))
    return ok({ id: `d${S.seq}:${String(body?.lookId)}`, lookId: body?.lookId, decision: body?.decision })
  }
  const dd = m(/^\/studio\/match\/decisions\/d\d+:(.+)$/)
  if (method === "DELETE" && dd) {
    const decision=decisions.get(path.slice("/studio/match/decisions/".length))
    if(decision?.added) S.saved.delete(decision.lookId)
    decisions.delete(path.slice("/studio/match/decisions/".length))
    return ok(null, 204)
  }
  return err(404, "not_found", `Rota não disponível na prévia: ${method} ${path}`)
}


